
public class PrintEvenCountForaGivenrRange {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
     int count=0;
     for(int i=23;i<=60;i++) {
    	 if(i % 2==0) {
    		 count++;
    	 }
     }
     System.out.println("The count of even numbers is: "+count);
	}

}
/*
The count of even numbers is: 19
*/